select case when products.stock_qty >= 433 then 'high' when products.stock_qty >= 69 then 'mid' else 'low' end as stock_qty_bucket, min(inventory.quantity) as min_quantity, sum(inventory.quantity) as total_quantity from inventory full outer join products on inventory.product_id = products.id left join suppliers on suppliers.id = products.supplier_id group by case when products.stock_qty >= 433 then 'high' when products.stock_qty >= 69 then 'mid' else 'low' end having min(inventory.quantity) >= 100 order by 1 limit 50
